  NyiakengPuachue: 0x1E140, Wancho: 0x1E2F0, Adlam: 0x1E950,
  Segmented: 0x1FBF0,
};
const lines = [];
const push = (l, v) => lines.push(l + '\t' + v);
for (const [name, base] of Object.entries(fams)) {
  const d = n => String.fromCodePoint(base + n);
  // slot p1 = hour ones (\d)
  push(`${name}/p1_hour_ones_10`, '1' + d(0));           // hour 10 -> expect OK
  push(`${name}/p1_hour_ones_24`, '2' + d(4));           // hour 24 -> expect 547
  push(`${name}/p1_hour_ones_19`, '1' + d(9) );          // hour 19 -> OK
  // slot p0 = hour tens ([0-2] ASCII)
  push(`${name}/p0_hour_tens`, d(1) + '0');              // expect 514 unless ASCII
  // slot p4 = minute ones (\d)
  push(`${name}/p4_min_ones`, '10:3' + d(0));            // OK
  push(`${name}/p4_min_ones_9`, '10:5' + d(9));          // minute 59 OK
  // slot p3 = minute tens ([0-5] ASCII)
  push(`${name}/p3_min_tens`, '10:' + d(3) + '0');       // 514 unless ASCII
  // slot p7 = second ones (\d)
  push(`${name}/p7_sec_ones`, '10:30:3' + d(0));         // OK
  // slot p6 = second tens ([0-5] ASCII)
  push(`${name}/p6_sec_tens`, '10:30:' + d(3) + '0');    // 514 unless ASCII
