  'U+2170 SMALL_ROMAN_I': 0x2170, 'U+3007 IDEOGRAPHIC_ZERO': 0x3007,
  'U+3021 HANGZHOU_ONE': 0x3021, 'U+4E00 CJK_ONE': 0x4E00,
  'U+96F6 CJK_ZERO_LING': 0x96F6, 'U+1D7CD MATH_BOLD_pre': 0x1D7CD,
  'U+1FBFA post_segmented': 0x1FBFA, 'U+0F33 TIBETAN_HALF_ZERO': 0x0F33,
  'U+19DA NEWTAILUE_THAM_ONE': 0x19DA, 'U+2189 ZERO_THIRDS': 0x2189,
  'U+16EE RUNIC_ARLAUG': 0x16EE, 'U+FF19+1 U+FF1A COLON_FULLWIDTH': 0xFF1A,
  'U+06F0-1 U+06EF': 0x06EF, 'U+0669+1 U+066A': 0x066A,
  'U+0966-1 U+0965': 0x0965, 'U+09EF+1 U+09F0': 0x09F0,
  'U+A8D9+1 U+A8DA': 0xA8DA, 'U+2007 FIGURE_SPACE': 0x2007,
  'U+2044 FRACTION_SLASH': 0x2044, 'U+00B0 DEGREE': 0x00B0,
};
for (const [name, cp] of Object.entries(nonNd)) {
  push(`NONND ${name} /p1`, '1' + String.fromCodePoint(cp));
  push(`NONND ${name} /p4`, '10:3' + String.fromCodePoint(cp));
}
writeFileSync('/tmp/cases.tsv', lines.join('\n') + '\n', 'utf8');
console.log('cases:', lines.length);
EOF
