import { writeFileSync } from 'node:fs';
const nd = [];
for (let cp = 0; cp <= 0x10FFFF; cp++) {
  if (cp >= 0xD800 && cp <= 0xDFFF) continue;
  if (/^\p{Nd}$/u.test(String.fromCodePoint(cp))) nd.push(cp);
}
console.log('node18 \\p{Nd} count =', nd.length);
// contiguous runs
const runs = [];
let s = nd[0], p = nd[0];
for (const c of nd.slice(1)) { if (c === p + 1) { p = c; } else { runs.push([s, p]); s = c; p = c; } }
runs.push([s, p]);
console.log('runs =', runs.length);
console.log(runs.map(([a,b]) => `U+${a.toString(16).toUpperCase().padStart(4,'0')}..U+${b.toString(16).toUpperCase().padStart(4,'0')}(${b-a+1})`).join(' '));
const lines = [];
for (const cp of nd) lines.push('ND:' + cp.toString(16).toUpperCase() + '\t1' + String.fromCodePoint(cp) + ':30');
// neighbours just outside each run
const nbrs = new Set();
for (const [a,b] of runs) { if (a-1 >= 0) nbrs.add(a-1); if (b+1 <= 0x10FFFF) nbrs.add(b+1); }
for (const cp of nbrs) {
  if (cp >= 0xD800 && cp <= 0xDFFF) continue;
  lines.push('NB:' + cp.toString(16).toUpperCase() + '\t1' + String.fromCodePoint(cp) + ':30');
}
writeFileSync('/tmp/nd_cases.tsv', lines.join('\n') + '\n', 'utf8');
console.log('cases', lines.length);
EOF
